const dictionaries: Record<KybLocale, Dictionary> = { en: {}, es, pt, ru };

export const resolveKybLocale = (pathname: string): KybLocale => {
	const value = pathname.split('/').filter(Boolean)[0]?.toLowerCase();
	return value === 'es' || value === 'pt' || value === 'ru' ? value : 'en';
};

export const translateKyb = (locale: KybLocale, source: string, values: Record<string, string | number> = {}) => {
	let result = dictionaries[locale][source] || source;
	Object.entries(values).forEach(([key, value]) => { result = result.replaceAll(`{${key}}`, String(value)); });
	return result;
};
